<?php require 'common.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($id){$stmt=$db->prepare('SELECT filename FROM project_archives WHERE project_id=?');$stmt->execute([$id]);$archive=$stmt->fetchColumn();$db->prepare('DELETE FROM project_archives WHERE project_id=?')->execute([$id]);$stmt=$db->prepare('DELETE FROM projects WHERE id=?');$stmt->execute([$id]);if($archive&&preg_match('/^[a-f0-9]{32}\.zip$/',$archive))@unlink(dirname(__DIR__).'/data/project-archives/'.$archive);}header('Location: projects.php');exit;}layout_start('Manage projects');?><div class="actions"><a class="primary" href="project.php">+ Add new project</a></div><section class="panel" style="margin:20px 0;padding:20px"><h2>Local project websites</h2><p>Copy your website into <code>projects/your-folder/</code>, then add its path as <code>projects/your-folder/index.php</code> in Add new project. No upload/import feature is enabled.</p></section><div class="panel table-scroll"><table><thead><tr><th>Project</th><th>Technology</th><th>Link</th><th>Actions</th></tr></thead><tbody><?php foreach($db->query('SELECT * FROM projects ORDER BY sort_order,id') as $p):?><tr><td><strong><?=h($p['title'])?></strong><small><?=h($p['description'])?></small></td><td><?=h($p['stack'])?></td><td><?php if(project_url($p['url'])):?><a href="<?=h(project_url($p['url']))?>" target="_blank" rel="noopener noreferrer">Visit →</a><?php else:?>—<?php endif;?></td><td><a class="secondary" href="project.php?id=<?=(int)$p['id']?>">Edit</a><form method="post" class="inline" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php layout_end(); ?>
